<?php require __DIR__.'/includes/header.php'; $cid=currentCompanyId(); $scope=$cid?' WHERE company_id='.$cid:''; function countQ($table,$scope){return (int)db()->query("SELECT COUNT(*) FROM $table".$scope)->fetchColumn();} $companies=isAdmin()?countQ('companies',''):1; $workers=countQ('workers',$scope);$projects=countQ('projects',$scope);$permits=countQ('permits',$scope);$requests=countQ('update_requests',$scope); ?>
<h1><?=t('dashboard')?></h1><div class="grid stats"><div><b><?=$companies?></b><span><?=t('companies')?></span></div><div><b><?=$workers?></b><span><?=t('workers')?></span></div><div><b><?=$projects?></b><span><?=t('projects')?></span></div><div><b><?=$permits?></b><span><?=t('permits')?></span></div><div><b><?=$requests?></b><span><?=t('requests')?></span></div></div>
<div class="grid two"><section class="card"><h3><?=t('requests')?></h3><?php $st=db()->query('SELECT status,COUNT(*) c FROM update_requests'.($scope?:'').' GROUP BY status'); foreach($st as $r):?><p><span class="badge <?=$r['status']?>"><?=e($r['status'])?></span> <b><?=$r['c']?></b></p><?php endforeach;?></section><section class="card"><h3><?=t('company_profile')?></h3><p><?=t('company_only')?></p><a class="btn primary" href="company-profile.php"><?=t('view')?></a></section></div><?php require __DIR__.'/includes/footer.php'; ?>
